-- Generated by scripts/generate-claude-provider-schema.mjs.
-- Run once per shard with bound backfillFrom/backfillTo; at most one day per invocation.
-- Repeatable, including overlaps with the live MV. Does not activate the read path.
SELECT throwIf({backfillTo:DateTime('UTC')} <= {backfillFrom:DateTime('UTC')}
  OR dateDiff('second', {backfillFrom:DateTime('UTC')}, {backfillTo:DateTime('UTC')}) > 86400,
  'Claude provider backfill requires a positive interval of at most one day');

INSERT INTO claude_code.claude_session_providers_v1 (hour, SessionId, Provider)
SELECT toStartOfHour(toDateTime(TimeUnix)) AS hour, SessionId,
    Attributes['anthropic.provider'] AS Provider
  FROM claude_code.otel_metrics_sum
  WHERE SessionId != '' AND Attributes['anthropic.provider'] != '' AND (TimeUnix >= {backfillFrom:DateTime('UTC')} AND TimeUnix < {backfillTo:DateTime('UTC')})
  GROUP BY hour, SessionId, Provider;
